<?php
declare(strict_types=1);namespace App\Http\Requests\Finance;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;class PaymentRequest extends FormRequest{public function authorize():bool{return $this->user()?->can('finance.payment.create-manual')??false;}public function rules():array{return ['invoice_id'=>'required|exists:student_invoices,id','paid_at'=>'required|date','amount'=>'required|integer|min:1','payment_method'=>['required',Rule::in(['cash','bank_transfer','bri_briva'])],'bank_reference'=>'nullable|required_unless:payment_method,cash|string|max:255|unique:student_payments,bank_reference','note'=>'nullable|string|max:500'];}}
